layers.vertex:
attribute vec3 aO; attribute float aT, aS; uniform float uTime; varying vec2 vP; varying float vU, vS;
    void main(){ float u = uTime - aT; if (u < 0. || u > 0.18){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vec4 mv = viewMatrix*vec4(aO, 1.); mv.xyz += normalize(-mv.xyz)*.3; mv.xy += position.xy*.42;
      vP = position.xy*.42; vU = u; vS = aS; gl_Position = projectionMatrix*mv; }

layers.fragment:
uniform vec3 uDot, uDotL; varying vec2 vP; varying float vU, vS;
    void main(){
      vec2 p = vP; float lum = 0., hot = 0.;
        float t = vU/0.18, f = pow(1. - t, 1.4)*(vU < .033 ? 1.7 : 1.), r = length(p), a = atan(p.y, p.x);
        float k = 1. - pow(1. - clamp(t/.6, 0., 1.), 3.);
        lum += exp(-r*r*(90. + 400.*t))*f*1.3;                                   // splat core
        for (int j = 0; j < 8; j++){
          float fj = float(j), h = fract(sin(fj*71.3 + vS*13.)*4375.5), aj = fj*.785 + h*.6;
          vec2 dir = vec2(cos(aj), sin(aj)); float Rj = (.12 + .2*h)*k;           // each droplet flies its own distance
          vec2 q = p - dir*Rj; float sz = (.018 + .014*fract(h*7.))*(1. - .6*t);
          float al = dot(q, dir), ac = dot(q, vec2(-dir.y, dir.x));
          lum += exp(-(ac*ac)/(sz*sz) - (al*al)/(sz*sz*4.))*f;                  // stretched along its motion
        }
        hot = lum*.45;
      vec3 o = (uDot*lum + mix(uDot, uDotL, .7)*hot)*smoothstep(.42, .34, length(p));
      if (max(o.r, max(o.g, o.b)) < .002) discard;
      gl_FragColor = vec4(o, 1.); }
